# 별도 실습 폴더의 main.py에 저장
# 4강에서 만든 환경과 fastapi[standard] 사용
from fastapi import FastAPI, HTTPException
app = FastAPI()
records = {1: {'topic': 'SQL', 'minutes': 40}}

@app.get('/sessions/{session_id}')
def read_session(session_id: int):
    if session_id not in records:
        raise HTTPException(status_code=404, detail='학습 기록을 찾을 수 없습니다')
    return records[session_id]

# 실행: fastapi dev main.py
# 요청 실행과 상태 코드 확인: http://127.0.0.1:8000/docs

